def clear_stale_pending_flags(apps, schema_editor):
    """Anyone flagged "assessments pending" who has no pending/in-progress assessment is not actually waiting on anything
    (the flag used to default to pending for every new person). Set them to complete."""
    User = apps.get_model('accounts', 'User')
    Assignment = apps.get_model('assessments', 'CandidateAssignment')
    Candidate = apps.get_model('recruitment', 'Candidate')
    waiting_statuses = ['pending', 'in_progress']
    waiting_employees = set(Assignment.objects.filter(status__in=waiting_statuses, employee__isnull=False).values_list('employee_id', flat=True))
    waiting_candidates = set(Assignment.objects.filter(status__in=waiting_statuses, candidate__isnull=False).values_list('candidate_id', flat=True))
    waiting_portal_users = set(Candidate.objects.filter(pk__in=waiting_candidates, portal_user__isnull=False).values_list('portal_user_id', flat=True))
    keep = waiting_employees | waiting_portal_users
    User.objects.filter(assessment_status='pending').exclude(pk__in=keep).update(assessment_status='complete')


